'use strict';
const Privacy=MedPrivacy;
let referenceRecords=[],referencePassword='',referenceDB=null,vaultPending=[],privacyBusy=false,privacyImportBusy=false;
async function referenceStore(){if(referenceDB)return referenceDB;referenceDB=await new Promise((resolve,reject)=>{const r=indexedDB.open('medannotate-private-references',1);r.onupgradeneeded=()=>r.result.createObjectStore('vault');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});return referenceDB}
async function readReferenceEnvelope(){const d=await referenceStore();return new Promise((resolve,reject)=>{const r=d.transaction('vault').objectStore('vault').get('encrypted');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function saveReferenceVault(){C.check(referencePassword,'Unlock the private reference vault');const encrypted=await Privacy.encrypt(referenceRecords,referencePassword),d=await referenceStore();await new Promise((resolve,reject)=>{const tx=d.transaction('vault','readwrite');tx.objectStore('vault').put(encrypted,'encrypted');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});return encrypted}
async function unlockReferences(){if(referencePassword)return;const existing=await readReferenceEnvelope();await new Promise((resolve,reject)=>{let settled=false;modal(`<h2>${existing?'Unlock':'Create'} private reference vault</h2><p>The internal reference sheet links original filenames and patient identifiers to neutral case names. It is encrypted separately and is never included in annotation or training exports.</p><label>Passphrase — at least 12 characters<input id="referencePassword" type="password" autocomplete="${existing?'current-password':'new-password'}"></label>${existing?'':'<label>Confirm passphrase<input id="referencePassword2" type="password" autocomplete="new-password"></label>'}<p class="hint">Keep this passphrase securely. It cannot be recovered by the application. After importing, download an encrypted reference backup for internal storage.</p><button id="unlockReference" class="primary wide">${existing?'Unlock':'Create vault'}</button>`);$('dialog').addEventListener('close',()=>{if(!settled)reject(Error('Import canceled: reference vault remains locked'))},{once:true});bind('unlockReference',async()=>{const password=$('referencePassword').value;C.check(password.length>=12,'Use at least 12 characters');if(!existing)C.check(password===$('referencePassword2').value,'Passphrases do not match');const records=existing?await Privacy.decrypt(existing,password):[];C.check(Array.isArray(records),'Invalid reference records');referenceRecords=records;referencePassword=password;for(const c of project.cases){if(!c.synthetic&&!c.privacy){if(!referenceRecords.some(r=>r.caseId===c.id))referenceRecords.push({caseId:c.id,subjectCode:c.group,originalName:c.name,sources:[c.name],created:new Date().toISOString()});c.name=c.id;c.sequence='Sequence not retained — verify acquisition';c.privacy={state:'pending',metadataSanitized:true,method:'Canonical image; legacy metadata migrated',created:new Date().toISOString()}}}await saveReferenceVault();changed();settled=true;$('dialog').close();resolve()})})}
const previousMakeCase=makeCase;
makeCase=function(volume,originalName){const {privateIdentity,...safeVolume}=volume,c=previousMakeCase(safeVolume,originalName);if(volume.modality==='SYNTHETIC')return c;const identity=privateIdentity||{},existing=identity.patientId?[...referenceRecords,...vaultPending].find(r=>r.patientId===identity.patientId&&r.issuer===(identity.issuer||'')):null,subject=existing?.subjectCode||'SUBJ_'+crypto.randomUUID().replace(/-/g,'').slice(0,16);c.name=c.id;c.group=subject;c.modality=['MR','CT','CR','DX','IO','PX','US','PT','NM','MG','OT'].includes(volume.modality)?volume.modality:(volume.modality==='2D image'?'2D image':'UNKNOWN');c.sequence='Sequence not retained — verify acquisition';c.fieldStrength=/^\d+(\.\d+)?$/.test(String(volume.fieldStrength||''))?volume.fieldStrength:'Not supplied';c.privacy={state:'pending',metadataSanitized:true,method:'Canonical scalar NIfTI; original header fields and extensions excluded',created:new Date().toISOString(),ocr:null,facialReview:false};vaultPending.push({caseId:c.id,subjectCode:subject,originalName,patientId:identity.patientId||'',patientName:identity.patientName||'',issuer:identity.issuer||'',studyUID:identity.studyUID||'',seriesUID:identity.seriesUID||'',sources:identity.sources||[identity.source||originalName],created:new Date().toISOString()});return c};
const previousImport=importFiles;
importFiles=async function(files){C.check(!privacyImportBusy,'An import is already running');privacyImportBusy=true;try{await unlockReferences();vaultPending=[];await previousImport(files);referenceRecords.push(...vaultPending);vaultPending=[];await saveReferenceVault();}catch(e){referenceRecords.push(...vaultPending);vaultPending=[];if(referencePassword)await saveReferenceVault().catch(()=>{});throw e}finally{privacyImportBusy=false}};
async function syncPrivateGroup(caseId,group){const r=referenceRecords.find(r=>r.caseId===caseId);if(r){r.subjectCode=group;await saveReferenceVault()}}
const previousReviewErrors=reviewErrors;
reviewErrors=function(c){const errors=previousReviewErrors(c);if(!c.synthetic&&c.privacy?.state!=='approved')errors.unshift('Complete privacy intake and clearance');return errors};
const previousPointerDown=cv.onpointerdown;
cv.onpointerdown=safe(e=>{const c=current();if(c&&!c.synthetic&&c.privacy?.state!=='approved'&&e.button===0){message('Complete Privacy intake before annotation. Metadata was stripped, but pixel and facial checks are still pending.',true);return}return previousPointerDown(e)});
bind('references',async()=>{await unlockReferences();modal(`<h2>Private reference sheet</h2><p><b>${referenceRecords.length}</b> mappings are encrypted in this browser profile. This sheet is separate from datasets and must stay inside your approved internal environment.</p><div class="info-box">Naming: ECAR_PROJECTKEY_000001, ECAR_PROJECTKEY_000002… for new cases; SUBJ_… for subject groups. Existing CASE_… IDs remain valid. No names, dates of birth, hospital IDs or diagnosis words are used in neutral case filenames.</div><button id="backupReferences" class="primary wide">Download encrypted reference backup</button><button id="exportReferenceCSV" class="wide">Export internal reference CSV…</button><button id="restoreReferences" class="wide">Restore encrypted reference backup</button><button id="lockReferences" class="wide">Lock reference vault</button>`);bind('backupReferences',async()=>{const data=await saveReferenceVault();download(new Blob([JSON.stringify(data)],{type:'application/json'}),'MedAnnotate-private-references.medrefs')});bind('exportReferenceCSV',()=>{C.check(confirm('This CSV contains original identifying information. Save it only in your protected internal location. It must never be delivered with a training dataset.'),'CSV export canceled');download(new Blob([Privacy.referenceCSV(referenceRecords)],{type:'text/csv'}),'PRIVATE-MedAnnotate-reference.csv')});bind('restoreReferences',()=>$('referenceBackup').click());bind('lockReferences',()=>{C.check(!privacyImportBusy,'Wait for the import to finish');referencePassword='';referenceRecords=[];$('dialog').close();message('Reference vault locked.')})});
$('referenceBackup').onchange=safe(async e=>{const f=e.target.files[0];if(!f)return;const envelope=JSON.parse(await f.text());modal('<h2>Restore reference backup</h2><label>Backup passphrase<input id="backupPass" type="password"></label><button id="restoreVaultNow" class="primary wide">Merge protected reference records</button>');bind('restoreVaultNow',async()=>{const rows=await Privacy.decrypt(envelope,$('backupPass').value);C.check(Array.isArray(rows),'Invalid reference backup');for(const r of rows){const existing=referenceRecords.find(x=>x.caseId===r.caseId);C.check(!existing||JSON.stringify(existing)===JSON.stringify(r),'Conflicting mapping for '+r.caseId+'; keep the backups separate');if(!existing)referenceRecords.push(r)}await saveReferenceVault();$('dialog').close();message('Reference records merged into the protected vault.')});e.target.value=''});
async function ensureOCR(){if(window.Tesseract)return;await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='ocr/tesseract.min.js';s.onload=resolve;s.onerror=()=>reject(Error('Bundled OCR engine could not load'));document.head.append(s)})}
function privacyCanvas(c,z){const p=C.plane(c.dims,2,z),native=document.createElement('canvas');native.width=p.w;native.height=p.h;const cc=native.getContext('2d'),img=cc.createImageData(p.w,p.h);let low=Infinity,high=-Infinity;for(let y=0;y<p.h;y++)for(let x=0;x<p.w;x++){const v=c.data[p.index(x,y)];low=Math.min(low,v);high=Math.max(high,v)}for(let y=0;y<p.h;y++)for(let x=0;x<p.w;x++){let v=(c.data[p.index(x,y)]-low)*255/(high-low||1);if(c.inverse)v=255-v;const o=(x+y*p.w)*4;img.data[o]=img.data[o+1]=img.data[o+2]=v;img.data[o+3]=255}cc.putImageData(img,0,0);const scale=Math.min(2,Math.max(1,1200/Math.max(p.w,p.h))),out=document.createElement('canvas');out.width=Math.round(p.w*scale);out.height=Math.round(p.h*scale);out.getContext('2d').drawImage(native,0,0,out.width,out.height);return {canvas:out,scale:out.width/p.w}}
async function runPrivacyOCR(c,redact){C.check(!privacyBusy,'Privacy scan already running');C.check(c.privacy?.state!=='approved','Reopen privacy review before rescanning');C.check(!redact||!c.mask.some(x=>x),'With existing annotations, turn off automatic masking for a read-only scan');C.check(c.dims[2]<=2000,'OCR batch limit is 2,000 slices');await ensureOCR();privacyBusy=true;let worker;const regions=[];try{const base=new URL('ocr/',location.href).href;worker=await Tesseract.createWorker('eng',1,{workerPath:base+'worker.min.js',corePath:base+'tesseract-core-lstm.wasm.js',langPath:base,workerBlobURL:false,cacheMethod:'none',gzip:true});await worker.setParameters({tessedit_pageseg_mode:'11'});for(let z=0;z<c.dims[2];z++){const {canvas,scale}=privacyCanvas(c,z),result=await worker.recognize(canvas,{}, {blocks:true,text:true}),boxes=Privacy.boxesFromOCR(result.data,c.dims[0],c.dims[1],scale);if(boxes.length)regions.push({k:z,boxes});message(`Local privacy OCR: slice ${z+1} / ${c.dims[2]}`);if($('privacyProgress'))$('privacyProgress').textContent=`Scanning slice ${z+1} of ${c.dims[2]}`}
const changedVoxels=redact?Privacy.redact(c,regions):0;c.privacy??={metadataSanitized:true};c.privacy.ocr={engine:'Tesseract 6 / English',scannedSlices:c.dims[2],regions:regions.reduce((n,r)=>n+r.boxes.length,0),redacted:!!redact,changedVoxels,at:new Date().toISOString(),limitations:'English OCR can miss text and over-detect anatomy. It is not a privacy guarantee.'};c.privacy.state='awaiting-review';c.privacy.redactions=redact?regions:[];invalidate(c);audit('privacy-ocr',{caseId:c.id,slices:c.dims[2],regions:c.privacy.ocr.regions,redacted:!!redact});draw();return c.privacy.ocr}finally{if(worker)await worker.terminate();privacyBusy=false}}
bind('privacy',()=>{const c=current();C.check(c,'Import a case first');c.privacy??={state:'pending',metadataSanitized:true,method:'Canonical image representation; verify legacy free-text fields',created:new Date().toISOString()};modal(`<h2>Privacy intake · ${esc(c.id)}</h2><p>Original headers are excluded from the annotation image. OCR runs locally across every K slice; detected text can be masked automatically. Source files are not modified.</p><div class="privacy-stages"><div><b>1</b><span>Metadata<br><strong>${c.privacy.metadataSanitized?'Stripped':'Pending'}</strong></span></div><div><b>2</b><span>Pixel text<br><strong>${c.privacy.ocr?'Scanned':'Not scanned'}</strong></span></div><div><b>3</b><span>Clearance<br><strong>${esc(c.privacy.state)}</strong></span></div></div><label class="check"><input id="autoRedactText" type="checkbox" checked>Automatically mask detected text boxes (may remove anatomy inside those boxes)</label><button id="runPrivacyOCR" class="primary wide">Scan all slices and process text</button><p id="privacyProgress" role="status">${c.privacy.ocr?`${c.privacy.ocr.scannedSlices} slices scanned; ${c.privacy.ocr.regions} text regions found.`:'OCR uses the bundled English model; no scan images are uploaded.'}</p><details><summary>Optional automated MRI defacing service</summary><p class="hint">Recognizable face structure requires a validated defacing process. The included PyDeface server adapter can run on a trusted local/remote system with FSL installed. No defacing engine is bundled.</p><label>Defacing endpoint<input id="defaceURL" placeholder="http://127.0.0.1:8768/deface"></label><label>Service token<input id="defaceToken" type="password"></label><label class="check"><input id="defaceConsent" type="checkbox">I approve sending this canonical NIfTI volume to this service.</label><button id="runDeface">Run connected defacing</button></details><div class="info-box">Metadata removal alone is not complete anonymization. OCR can miss text, and facial anatomy can remain identifiable. Clearance below records your privacy review; it does not certify anonymity.</div><label>Privacy reviewer ID<input id="privacyReviewer" value="${esc(c.privacy.reviewer||'')}"></label><label class="check"><input id="privacyPixels" type="checkbox">I verified residual identifiers and checked that text masking did not remove required anatomy.</label><label class="check"><input id="privacyFace" type="checkbox">Facial/reconstruction risk is absent or has been addressed by an approved process.</label><button id="approvePrivacy" class="wide primary">Clear this case for annotation</button><button id="holdPrivacy" class="wide">Keep in privacy review</button>`);bind('runPrivacyOCR',async()=>{const result=await runPrivacyOCR(c,$('autoRedactText').checked);if($('privacyProgress'))$('privacyProgress').textContent=`${result.scannedSlices} slices scanned. ${result.regions} regions found; ${result.redacted?'automatic masking applied':'no pixel changes applied'}. Review the result.`});bind('approvePrivacy',()=>{C.check(!privacyBusy,'Wait for privacy processing to finish');C.check(c.synthetic||c.privacy.ocr?.scannedSlices===c.dims[2],'Scan all slices first');C.check(c.synthetic||!c.privacy.ocr?.regions||c.privacy.ocr.redacted,'Detected text must be processed or the case held out');C.check($('privacyReviewer').value.trim()&&$('privacyPixels').checked&&$('privacyFace').checked,'Complete the privacy clearance checks');c.name=c.id;c.sequence='Sequence not retained — verify acquisition';c.privacy={...c.privacy,state:'approved',reviewer:$('privacyReviewer').value.trim(),facialReview:true,approvedAt:new Date().toISOString()};audit('privacy-cleared',{caseId:c.id,reviewer:c.privacy.reviewer});$('dialog').close();message('Privacy clearance recorded. You can now annotate this case.')});bind('holdPrivacy',()=>{c.privacy.state='held';c.releaseApproval=null;audit('privacy-held',{caseId:c.id});$('dialog').close();message('Case held out of annotation and export until privacy clearance.')});bind('runDeface',async()=>{C.check(!$('defaceConsent').checked?false:true,'Approve volume transmission first');C.check(!c.mask.some(x=>x>0),'Run defacing before annotation');const url=new URL($('defaceURL').value);C.check(url.protocol==='https:'||(url.protocol==='http:'&&['localhost','127.0.0.1','[::1]'].includes(url.hostname)),'Use HTTPS or a loopback service');C.check(!privacyBusy,'Wait for current privacy processing');c.privacy.state='held';c.releaseApproval=null;changed();const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/octet-stream',Authorization:'Bearer '+$('defaceToken').value},body:C.writeNifti(c),signal:AbortSignal.timeout(600000),redirect:'error'});C.check(response.ok,'Defacing service returned HTTP '+response.status);const bytes=await response.arrayBuffer(),r=C.nifti(bytes);C.check(c.dims.every((n,i)=>n===r.dims[i])&&c.affine.every((row,i)=>row.every((v,j)=>Math.abs(v-r.affine[i][j])<1e-4)),'Defacing changed image geometry; result rejected');c.data=r.data;c.privacy.defacing={at:new Date().toISOString(),outputSHA256:await hashBytes(bytes),service:url.hostname};c.privacy.state='pending';c.privacy.ocr=null;invalidate(c);audit('defacing-applied',{caseId:c.id});$('defaceToken').value='';draw();message('Defacing result applied. Run local OCR and complete privacy clearance.')})});

const previousModelClick=$('model').onclick;$('model').onclick=safe(()=>{C.check(current()?.synthetic||current()?.privacy?.state==='approved','Clear privacy intake before sending a slice to a segmentation service');return previousModelClick()});

// All mask-entry controls must obey the same intake gate, including keyboard shortcuts.
for(const id of ['accept','threshold','propagate','undo','redo']){const previous=$(id).onclick;$(id).onclick=safe(e=>{C.check(current()?.synthetic||current()?.privacy?.state==='approved','Clear Privacy intake before editing annotations');return previous(e)})}
const previousGroupChange=$('group').onchange;$('group').onchange=safe(async e=>{const c=current();if(!c)return;const group=$('group').value.trim();try{await unlockReferences();previousGroupChange(e);await syncPrivateGroup(c.id,group)}catch(error){$('group').value=c.group;throw error}});
